import { cacheTag, cacheLife } from 'next/cache'
import { getAllProducts } from '@/lib/db'

export async function getProducts() {
  'use cache'
  // Catalog reads are served from this cached entry until the "products" tag
  // is revalidated (e.g. by the admin "Sync latest catalog" action).
  cacheTag('products')
  cacheLife('max')

  return getAllProducts()
}

