import { revalidateTag } from 'next/cache'
import { getProducts } from '@/lib/products'

export default async function ProductsPage() {
  const products = await getProducts()

  async function syncLatestCatalog() {
    'use server'
    // Stale-while-revalidate: mark the "products" cache entries stale and
    // recompute them in the background. The admin's request (and everyone
    // else's) keeps getting the cached catalog instantly, and every view
    // tagged "products" picks up the fresh data shortly after — no request
    // blocks on the recompute.
    revalidateTag('products', 'max')
  }

  return (
    <div>
      <h1>Product Catalog</h1>

      <form action={syncLatestCatalog}>
        <button type="submit">Sync latest catalog</button>
      </form>

      <ul>
        {products.map((product) => (
          <li key={product.id}>
            {product.name} — ${product.price}
          </li>
        ))}
      </ul>
    </div>
  )
}

